<original_code>
#include <bits/stdc++.h>
#define add push_back
#define X first
#define Y second
#define int long long
#define read_array(a,n) for(int i=0;i<n;i++)cin>>a[i]
using namespace std;

template <class T,class L> T& max_value(T &x,L y){if(y>x)x=y;return x;}
template <class T,class L> T& min_value(T &x,L y){if(y<x)x=y;return x;}
typedef pair<int,int> pii;
const int MAX=200017;
unordered_map<int,int> memo;
int count_digits(int x){
  int cnt=0;
  while(x){
    cnt++;
    x/=10;
  }
  return cnt;
}
int reverse_num(int x){
  int arr[17],p=0;
  while(x){
    arr[p++]=(x%10)-(x<0?-1:1);
    x/=10;
  }
  int res=0;
  while(p--){
    res=res*10+arr[p];
  }
  return res;
}
int prev_value(int x){
  int c=0,orig=x;
  while(x){
    c*=10;
    c+=(x<0?-1:1);
    x/=10;
  }
  c*=10;
  c++;
  return orig - c;
}
int get_last(int x){
  while(x>=10)
    x/=10;
  return x;
}
int remove_leading(int x){
  int arr[17],p=0;
  while(x>=10){
    arr[p++]=x%10;
    x/=10;
  }
  int res=0;
  while(p--){
    res=res*10+arr[p];
  }
  return res;
}
int solve(int x){
  if(x<=11)return min(13 - x, x);
  if(memo[x])return memo[x];
  int n=0,t=1;
  while(t<x){
    t*=10;
    t++;
    n++;
  }
  if(x*2>=t)
    return memo[x]=min(solve(t - x)+n+1, (x/(t/10))*n+solve(x%(t/10)));
  return memo[x]=(x/(t/10))*n+solve(x%(t/10));
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int a;
  cin>>a;
  cout<<solve(a)<<'\n';
  return 0;
}
